# Micro-feasibility check (NOT the experiment): pure-stdlib cost of rare-itemset mining.
import random, time, itertools
from collections import Counter
random.seed(0)
n, m = 5000, 30
tx = [[j for j in range(m) if random.random() < 0.15] for _ in range(n)]
t0=time.time()
# level-wise (Apriori-style) enumeration down to very low minsupport
minsup = 0.002*n
cur = Counter()
for t in tx:
