levels = [ {k:v for k,v in cur.items() if v>=minsup} ]
freq = dict(levels[0])
k=2
while levels[-1]:
    prev = sorted(levels[-1])
    cands=set()
    for a,b in itertools.combinations(prev,2):
        u = a+b if a<b else b+a
        if len(set(u))==len(u) and all(tuple(s) in freq for s in itertools.combinations(sorted(u),k-1)):
            cands.add(tuple(sorted(u)))
    nxt=Counter()
    txsets=[set(t) for t in tx]
    for c in cands:
        cs=set(c)
        for t in txsets:
            if cs<=t: nxt[c]+=1
    levels.append({k2:v for k2,v in nxt.items() if v>=minsup})
    freq.update(levels[-1]); k+=1
    if k>4: break
print("frequent-at-0.2% itemsets:", len(freq), "| elapsed %.2fs"%(time.time()-t0))
